{"action": "replace_code", "code": "def solve(data):
    n = len(data)
    if n == 0:
        return []

    # Проверка пересечения для полуоткрытых интервалов [start, end)
    # Пересечение положительной длины: max(start1, start2) < min(end1, end2)
    def intersect(i, j):
        return max(data[i][0], data[j][0]) < min(data[i][1], data[j][1])

    seen = [False] * n
    groups = []

    for start in range(n):
        if seen[start]:
            continue

        # Используем BFS для корректного заполнения всех связанных узлов
        # Это гарантирует транзитивность и связность группы
        group = []
        queue = [start]
        seen[start] = True

        while queue:
            i = queue.pop(0)
            group.append(i)

            # Проверяем пересечение с ВСЕМИ невидимыми узлами, а не только со стеком
            for j in range(n):
                if not seen[j] and intersect(i, j):
                    seen[j] = True
                    queue.append(j)

        groups.append(sorted(group))

    return groups
